import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

maxred_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor max_reduce_dim(torch::Tensor x, int64_t dim);
"""

maxred_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Max-reduction over the middle dimension of a contiguous 3D tensor [B, R, N].
// Output shape: [B, N]. Optimization: one thread per output column with
// the full reduction over R kept inside the thread. Consecutive threads
// map to consecutive columns, so every warp load reads one full 128-byte
// contiguous cache line (perfect coalescing and DRAM row locality)
// instead of four scattered 32-byte sectors coming from R-slices ~16 MB
// apart. Eight independent accumulators hide the load latency; no shared
// memory, no warp shuffles and no __syncthreads are needed.
template <typename T>
__global__ void max_reduce_middle_kernel(const T* __restrict__ X,
                                         T* __restrict__ Y,
                                         int B, int R, int N)
{
  const T neg_inf = -std::numeric_limits<T>::infinity();
  const int64_t g = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  const int b = (int)(g / N);
  const int col = (int)(g - (int64_t)b * N);
  if (b >= B) {
    return;
  }
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)b * R * N),
                          make_shape(R, N),
                          make_stride(N, Int<1>{}));
  T acc0 = neg_inf, acc1 = neg_inf, acc2 = neg_inf, acc3 = neg_inf;
  T acc4 = neg_inf, acc5 = neg_inf, acc6 = neg_inf, acc7 = neg_inf;
  int r = 0;
  for (; r + 7 < R; r += 8) {
    acc0 = ::max(acc0, mX(r + 0, col));
    acc1 = ::max(acc1, mX(r + 1, col));
    acc2 = ::max(acc2, mX(r + 2, col));
    acc3 = ::max(acc3, mX(r + 3, col));
    acc4 = ::max(acc4, mX(r + 4, col));
    acc5 = ::max(acc5, mX(r + 5, col));
    acc6 = ::max(acc6, mX(r + 6, col));
    acc7 = ::max(acc7, mX(r + 7, col));
  }
  for (; r < R; ++r) {
    acc0 = ::max(acc0, mX(r, col));
  }
  acc0 = ::max(acc0, acc1);
  acc2 = ::max(acc2, acc3);
  acc4 = ::max(acc4, acc5);
  acc6 = ::max(acc6, acc7);
  acc0 = ::max(acc0, acc2);
  acc4 = ::max(acc4, acc6);
  const T res = ::max(acc0, acc4);
  Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)b * N),
                          make_shape(N),
                          make_stride(Int<1>{}));
  mY(col) = res;
}
torch::Tensor max_reduce_dim(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() == 3, "x must be 3D [B, R, N]");
  if (dim < 0) dim += x.dim();
  TORCH_CHECK(dim == 1, "custom kernel currently reduces over dim == 1");
  auto x_c = x.contiguous();
  const int64_t B = x_c.size(0);
  const int64_t R = x_c.size(1);
  const int64_t N = x_c.size(2);
  auto y = torch::empty({B, N}, x_c.options());
  constexpr int Threads = 256;
  dim3 block(Threads);
  const int64_t work_items = B * N;
  const int64_t blocks = (work_items + Threads - 1) / Threads;
  TORCH_CHECK(blocks <= 0x7fffffff, "invalid grid size");
  if (blocks == 0) {
    return y;
  }
  dim3 grid((unsigned)blocks, 1);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  max_reduce_middle_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)B, (int)R, (int)N);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_middle_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

maxred_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=maxred_cpp_decl,
    cuda_sources=maxred_cuda_src,
    functions=["max_reduce_dim"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Max reduction over a specific dimension, implemented with a single custom
    CUDA kernel written with CuTe tensors/layouts.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = maxred_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce_dim(x, self.dim)

